import React, { useState } from 'react';
import './styles.css';
import { LayoutDashboard, Wallet, ArrowLeftRight, Target, Calculator, Settings as Cog, TrendingUp, RefreshCw, PiggyBank, Menu, HandCoins, PiggyBank as BudgetIcon, Users } from 'lucide-react';
import useFinTrack from './hooks/useFinTrack';
import useDueDateNotifications from './hooks/useDueDateNotifications';
import { useLanguage } from './i18n/LanguageContext';
import LoginScreen  from './components/LoginScreen';
import ResetPasswordScreen from './components/ResetPasswordScreen';
import Dashboard     from './components/Dashboard';
import Accounts      from './components/Accounts';
import Transactions  from './components/Transactions';
import Budget        from './components/Budget';
import Beneficiaries from './components/Beneficiaries';
import Savings       from './components/Savings';
import LoansCredits  from './components/LoansCredits';
import LoanSimulator from './components/LoanSimulator';
import InvestmentSimulator from './components/InvestmentSimulator';
import Settings      from './components/Settings';
const NAV = [
  {id:'dashboard',    labelKey:'nav.dashboard',    Icon:LayoutDashboard, group:'main'},
  {id:'accounts',     labelKey:'nav.accounts',     Icon:Wallet,          group:'main'},
  {id:'transactions', labelKey:'nav.transactions', Icon:ArrowLeftRight,  group:'main'},
  {id:'loansCredits', labelKey:'nav.loansCredits', Icon:HandCoins,       group:'main'},
  {id:'budget',       labelKey:'nav.budget',       Icon:BudgetIcon,      group:'planning'},
  {id:'savings',      labelKey:'nav.savings',      Icon:Target,          group:'planning'},
  {id:'loan',         labelKey:'nav.loan',         Icon:Calculator,      group:'planning'},
  {id:'investment',   labelKey:'nav.investment',   Icon:PiggyBank,       group:'planning'},
  {id:'beneficiaries',labelKey:'nav.beneficiaries',Icon:Users,           group:'system'},
  {id:'settings',     labelKey:'nav.settings',     Icon:Cog,             group:'system'},
];
export default function App() {
  const [page, setPage] = useState('dashboard');
  const [navOpen, setNavOpen] = useState(false);
  const ft = useFinTrack();
  const { t, lang, toggleLang } = useLanguage();
  useDueDateNotifications(ft.loans, ft.settings, t);
  const GROUPS = {main:t('nav.group_main'), planning:t('nav.group_planning'), system:t('nav.group_system')};
  // Lien "mot de passe oublie" clique depuis l'email : Firebase redirige ici
  // avec ?mode=resetPassword&oobCode=... au lieu de sa page generique.
  const urlParams = new URLSearchParams(window.location.search);
  if (urlParams.get('mode') === 'resetPassword' && urlParams.get('oobCode')) {
    return <ResetPasswordScreen
      oobCode={urlParams.get('oobCode')}
      onDone={() => { window.location.href = window.location.pathname; }}/>;
  }
  if (ft.authState==='loading') return (
    <div style={{minHeight:'100vh',display:'flex',alignItems:'center',justifyContent:'center',background:'var(--bg)'}}>
      <div style={{textAlign:'center'}}>
        <div style={{fontSize:'1.6rem',fontWeight:800,marginBottom:16,color:'var(--text)',fontFamily:'var(--fd)'}}>
          Fin<em style={{color:'var(--g1)',fontStyle:'normal'}}>Track</em>
        </div>
        <RefreshCw size={20} style={{color:'var(--text3)',animation:'spin 1s linear infinite'}}/>
        <style>{`@keyframes spin{from{transform:rotate(0)}to{transform:rotate(360deg)}}`}</style>
      </div>
    </div>
  );
  if (!ft.user) return <LoginScreen
    onLogin={()=>ft.login()}
    onLoginEmail={(email,pw)=>ft.loginWithEmail(email,pw)}
    onSignUp={(email,pw)=>ft.signUp(email,pw)}
    onForgotPassword={(email)=>ft.forgotPassword(email)}
    gapiReady={ft.gapiReady} error={ft.error} loading={ft.loading}/>;
  const renderedGroups = [];
  return (
    <div className="shell">
      <header className="topbar">
        <button className="menu-toggle" onClick={()=>setNavOpen(v=>!v)} aria-label="Menu">
          <Menu size={22}/>
        </button>
        <div className="logo" style={{fontWeight:800}}>
          <TrendingUp size={20} style={{color:'var(--g1)'}}/>
          <span>Fin<em style={{fontStyle:'normal'}}>Track</em></span>
        </div>
        {ft.syncing && <div className="syncing-dot"/>}
        {ft.error && (
          <div onClick={()=>ft.setError(null)} style={{fontSize:12,color:'var(--red)',background:'var(--red-bg)',padding:'5px 12px',borderRadius:6,border:'1px solid rgba(229,62,62,.2)',cursor:'pointer',display:'flex',alignItems:'center',gap:6}}>
            ⚠ {ft.error.slice(0,50)}… ✕
          </div>
        )}
        <div className="topbar-right">
          <button className="lang-toggle" onClick={toggleLang} title="FR / EN">
            {lang.toUpperCase()}
          </button>
          <div className="rate-chip">
            <ArrowLeftRight size={11}/>
            1 USD = <b>{ft.settings?.usdToHtg||130} HTG</b>
          </div>
          <span className="user-name" onClick={()=>setPage('settings')}>
            {(ft.user?.name||ft.user?.displayName||'').split(' ')[0]}
          </span>
          <img className="avatar" src={ft.user?.picture||ft.user?.photoURL} alt="" onClick={()=>setPage('settings')}/>
        </div>
      </header>
      <div className={`sidebar-backdrop ${navOpen?'open':''}`} onClick={()=>setNavOpen(false)}/>
      <nav className={`sidebar ${navOpen?'open':''}`}>
        {NAV.map(({id,labelKey,Icon,group})=>{
          const sg=!renderedGroups.includes(group);
          if(sg) renderedGroups.push(group);
          return (
            <React.Fragment key={id}>
              {sg && <div className="nav-group-label">{GROUPS[group]}</div>}
              <div className={`nav-item ${page===id?'active':''}`} onClick={()=>{setPage(id);setNavOpen(false);}}>
                <Icon size={16}/>{t(labelKey)}
              </div>
            </React.Fragment>
          );
        })}
      </nav>
      <main className="main">
        {page==='dashboard'    && <Dashboard    accounts={ft.accounts} transactions={ft.transactions} savings={ft.savings} loans={ft.loans} settings={ft.settings} onNav={setPage}/>}
        {page==='accounts'     && <Accounts     accounts={ft.accounts} transactions={ft.transactions} settings={ft.settings} onAdd={ft.addAccount} onUpdate={ft.updateAccount} onDelete={ft.deleteAccount}/>}
        {page==='transactions' && <Transactions transactions={ft.transactions} accounts={ft.accounts} settings={ft.settings} categories={ft.categories} onAddCategory={ft.addCategory} beneficiaries={ft.beneficiaries} onAddBeneficiary={ft.addBeneficiary} onDeleteBeneficiary={ft.deleteBeneficiary} onAdd={ft.addTransaction} onUpdate={ft.updateTransaction} onDelete={ft.deleteTransaction} onAddLoan={ft.addLoan}/>}
        {page==='loansCredits' && <LoansCredits loans={ft.loans} accounts={ft.accounts} settings={ft.settings} onAdd={ft.addLoan} onUpdate={ft.updateLoan} onDelete={ft.deleteLoan} onAddTransaction={ft.addTransaction}/>}
        {page==='budget'       && <Budget       budgets={ft.budgets} transactions={ft.transactions} settings={ft.settings} categories={ft.categories} onAddCategory={ft.addCategory} onAdd={ft.addBudget} onUpdate={ft.updateBudget} onDelete={ft.deleteBudget}/>}
        {page==='beneficiaries'&& <Beneficiaries beneficiaries={ft.beneficiaries} onAdd={ft.addBeneficiary} onUpdate={ft.updateBeneficiary} onDelete={ft.deleteBeneficiary}/>}
        {page==='savings'      && <Savings      savings={ft.savings} onAdd={ft.addSaving} onUpdate={ft.updateSaving} onDelete={ft.deleteSaving}/>}
        {page==='loan'         && <LoanSimulator settings={ft.settings}/>}
        {page==='investment'   && <InvestmentSimulator settings={ft.settings}/>}
        {page==='settings'     && <Settings     user={ft.user} settings={ft.settings} onSave={ft.saveSetting} onLogout={ft.logout}/>}
      </main>
    </div>
  );
}
