import { useState, useEffect, useCallback, useRef } from 'react';
import {
  db, genId, signInWithGoogle, signInWithEmail, signUpWithEmail, resetPassword,
  authErrorMessage, signOutUser, subscribeToAuth,
} from '../firestoreApi';
// ─────────────────────────────────────────────────────────────────────────────
// Central hook: manages auth state + all CRUD against Firestore.
// (Anciennement base sur Google Sheets — voir sheetsApi.js pour l'ancienne
// version, conservee pour reference / migration.)
// ─────────────────────────────────────────────────────────────────────────────
export default function useFinTrack() {
  const [authState, setAuthState] = useState('loading'); // loading | authed
  const [user, setUser]           = useState(null);
  const [accounts,     setAccounts]     = useState([]);
  const [transactions, setTransactions] = useState([]);
  const [savings,      setSavings]      = useState([]);
  const [loans,        setLoans]        = useState([]);
  const [beneficiaries,setBeneficiaries] = useState([]);
  const [budgets,      setBudgets]      = useState([]);
  const [categories,   setCategories]   = useState([]);
  const [settings,     setSettings]     = useState({ usdToHtg: 130 });
  const [loading,      setLoading]      = useState(false);
  const [syncing,      setSyncing]      = useState(false);
  const [error,        setError]        = useState(null);
  const pollRef = useRef(null);
  // ── Fetch all data ─────────────────────────────────────────────────────
  // Chaque lecture tourne independamment via Promise.allSettled pour qu'un
  // echec isole (ex: aucun parametre encore enregistre) ne bloque pas les
  // autres et n'efface pas les donnees deja chargees avec succes.
  const fetchAll = useCallback(async () => {
    setSyncing(true);
    const [accsR, txsR, savsR, loansR, bensR, budsR, catsR, rateR] = await Promise.allSettled([
      db.readAll('accounts'),
      db.readAll('transactions'),
      db.readAll('savings'),
      db.readAll('loans'),
      db.readAll('beneficiaries'),
      db.readAll('budgets'),
      db.readAll('categories'),
      db.getSetting('usdToHtg'),
    ]);
    const failures = [];
    if (accsR.status === 'fulfilled') {
      setAccounts(accsR.value.filter(a => a.id));
    } else {
      failures.push(accsR.reason?.message || String(accsR.reason));
    }
    if (txsR.status === 'fulfilled') {
      setTransactions(txsR.value.filter(t => t.id).sort((a,b) => b.date.localeCompare(a.date)));
    } else {
      failures.push(txsR.reason?.message || String(txsR.reason));
    }
    if (savsR.status === 'fulfilled') {
      setSavings(savsR.value.filter(s => s.id));
    } else {
      failures.push(savsR.reason?.message || String(savsR.reason));
    }
    if (loansR.status === 'fulfilled') {
      setLoans(loansR.value.filter(l => l.id));
    } else {
      failures.push(loansR.reason?.message || String(loansR.reason));
    }
    if (bensR.status === 'fulfilled') {
      setBeneficiaries(bensR.value.filter(b => b.id).sort((a,b) => (a.name||'').localeCompare(b.name||'')));
    } else {
      failures.push(bensR.reason?.message || String(bensR.reason));
    }
    if (budsR.status === 'fulfilled') {
      setBudgets(budsR.value.filter(b => b.id));
    } else {
      failures.push(budsR.reason?.message || String(budsR.reason));
    }
    if (catsR.status === 'fulfilled') {
      setCategories(catsR.value.filter(c => c.id));
    } else {
      failures.push(catsR.reason?.message || String(catsR.reason));
    }
    if (rateR.status === 'fulfilled') {
      if (rateR.value) setSettings(s => ({ ...s, usdToHtg: Number(rateR.value) }));
    } else {
      failures.push(rateR.reason?.message || String(rateR.reason));
    }
    if (failures.length > 0) {
      setError('Erreur lecture: ' + failures.join(' | '));
    } else {
      setError(null);
    }
    setSyncing(false);
  }, []);
  // ── Ecoute l'etat de connexion Firebase ─────────────────────────────────
  // Firebase garde la session en cache automatiquement (IndexedDB), donc
  // pas besoin de gerer nous-memes localStorage pour l'utilisateur/le token.
  useEffect(() => {
    const unsubscribe = subscribeToAuth((firebaseUser) => {
      setUser(firebaseUser);
      setAuthState('authed');
      if (firebaseUser) {
        fetchAll();
      } else {
        setAccounts([]); setTransactions([]); setSavings([]); setLoans([]); setBeneficiaries([]); setBudgets([]); setCategories([]);
      }
    });
    return unsubscribe;
  }, [fetchAll]);
  // ── Sign in with Google ────────────────────────────────────────────────
  const login = useCallback(async () => {
    try {
      setError(null);
      setLoading(true);
      await signInWithGoogle();
      // onAuthStateChanged (ci-dessus) met a jour `user` et recharge les
      // donnees automatiquement, pas besoin de le refaire ici.
    } catch(e) {
      setError('Erreur connexion: ' + (e.message || JSON.stringify(e)));
    } finally {
      setLoading(false);
    }
  }, []);
  // ── Sign in / sign up with email + password ─────────────────────────────
  const loginWithEmail = useCallback(async (email, password) => {
    try {
      setError(null);
      setLoading(true);
      await signInWithEmail(email, password);
    } catch(e) {
      setError(authErrorMessage(e));
    } finally {
      setLoading(false);
    }
  }, []);
  const signUp = useCallback(async (email, password) => {
    try {
      setError(null);
      setLoading(true);
      await signUpWithEmail(email, password);
    } catch(e) {
      setError(authErrorMessage(e));
    } finally {
      setLoading(false);
    }
  }, []);
  const forgotPassword = useCallback(async (email) => {
    try {
      setError(null);
      await resetPassword(email);
      return true;
    } catch(e) {
      setError(authErrorMessage(e));
      return false;
    }
  }, []);
  // ── Sign out ───────────────────────────────────────────────────────────
  const logout = useCallback(async () => {
    await signOutUser();
    setUser(null);
    setAccounts([]); setTransactions([]); setSavings([]); setLoans([]); setBeneficiaries([]); setBudgets([]); setCategories([]);
  }, []);
  // ── CRUD helpers ───────────────────────────────────────────────────────
  const refresh = useCallback(() => fetchAll(), [fetchAll]);
  const withSync = useCallback(async (fn) => {
    setSyncing(true);
    try {
      await fn();
      await fetchAll();
    }
    catch(e) { setError('Erreur: ' + (e.message || e)); }
    finally { setSyncing(false); }
  }, [fetchAll]);
  // accounts
  const addAccount     = (data) => withSync(() => db.append('accounts', { ...data, id: genId() }));
  const updateAccount  = (id, data) => withSync(() => db.update('accounts', id, data));
  const deleteAccount  = (id) => withSync(() => db.delete('accounts', id));
  // transactions
  const addTransaction    = (data) => withSync(() => db.append('transactions', { ...data, id: genId() }));
  const updateTransaction = (id, data) => withSync(() => db.update('transactions', id, data));
  const deleteTransaction = (id) => withSync(() => db.delete('transactions', id));
  // savings
  const addSaving    = (data) => withSync(() => db.append('savings', { ...data, id: genId() }));
  const updateSaving = (id, data) => withSync(() => db.update('savings', id, data));
  const deleteSaving = (id) => withSync(() => db.delete('savings', id));
  // loans & credits (creances, dettes, prets, obligations)
  const addLoan    = (data) => withSync(() => db.append('loans', { ...data, id: genId() }));
  const updateLoan = (id, data) => withSync(() => db.update('loans', id, data));
  const deleteLoan = (id) => withSync(() => db.delete('loans', id));
  // beneficiaires (liste reutilisable dans les transactions)
  const addBeneficiary    = (data) => withSync(() => db.append('beneficiaries', { ...data, id: genId() }));
  const updateBeneficiary = (id, data) => withSync(() => db.update('beneficiaries', id, data));
  const deleteBeneficiary = (id) => withSync(() => db.delete('beneficiaries', id));
  // budgets (plafonds hebdo/mensuels par categorie)
  const addBudget    = (data) => withSync(() => db.append('budgets', { ...data, id: genId() }));
  const updateBudget = (id, data) => withSync(() => db.update('budgets', id, data));
  const deleteBudget = (id) => withSync(() => db.delete('budgets', id));
  // categories personnalisees (en plus des categories integrees a l'app)
  // Respecte un id deja fourni par l'appelant (ex: pour selectionner tout de
  // suite la categorie fraichement creee dans un menu deroulant).
  const addCategory = (data) => withSync(() => db.append('categories', { ...data, id: data.id || genId() }));
  // settings
  const saveSetting = async (key, value) => {
    await db.setSetting(key, value);
    setSettings(s => ({ ...s, [key]: value }));
  };
  return {
    // auth
    authState, user, gapiReady: true, login, loginWithEmail, signUp, forgotPassword, logout,
    // data
    accounts, transactions, savings, loans, beneficiaries, budgets, categories, settings,
    loading, syncing, error, refresh,
    // CRUD
    addAccount, updateAccount, deleteAccount,
    addTransaction, updateTransaction, deleteTransaction,
    addSaving, updateSaving, deleteSaving,
    addLoan, updateLoan, deleteLoan,
    addBeneficiary, updateBeneficiary, deleteBeneficiary,
    addBudget, updateBudget, deleteBudget,
    addCategory,
    saveSetting,
    // helpers
    setError,
  };
}
